public static function getLocationOccupancyData($selectedDate)
{
    $db    = Factory::getContainer()->get('DatabaseDriver');
    $query = $db->getQuery(true);

    // 1. Get all Locations
    $query->select($db->quoteName(['id', 'title', 'latitude', 'longitude']))
          ->from($db->quoteName('#__yourcomponent_locations'));
    $db->setQuery($query);
    $locations = $db->loadObjectList('id');

    if (empty($locations)) {
        return [];
    }

    // Initialize occupancy counter
    foreach ($locations as $loc) {
        $loc->total_participants = 0;
        $loc->groups = [];
    }

    // 2. Query Reservations for the selected date
    // (Assuming date_first_stop is the date filter, or adjust if you track date per stop)
    $resQuery = $db->getQuery(true)
        ->select('*')
        ->from($db->quoteName('#__yourcomponent_reservations'))
        ->where($db->quoteName('date_first_stop') . ' = ' . $db->quote($selectedDate));

    $db->setQuery($resQuery);
    $reservations = $db->loadObjectList();

    // 3. Loop through reservations and iterate through stops (1 to 10)
    foreach ($reservations as $res) {
        for ($i = 1; $i <= 10; $i++) {
            $stopField = 'stop_' . $i; // e.g., stop_1, stop_2 ...
            
            if (!empty($res->$stopField) && isset($locations[$res->$stopField])) {
                $locationId = $res->$stopField;
                
                // Add participants to the location total
                $locations[$locationId]->total_participants += (int) $res->participants;
                
                // Collect group names for popup info
                $locations[$locationId]->groups[] = [
                    'group_name'   => $res->group_name,
                    'participants' => $res->participants
                ];
            }
        }
    }

    return array_values($locations);
}
